messages.content:
Tool response:
Tool: find_doctors
Description: Filter doctors by the supplied name and return matching IDs and names.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Doctor's full name",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: find_appointments_by_doctor_and_date
Description: Retrieve all scheduled appointments for a given doctor on a specified date.
Parameters:
    {
      "type": "object",
      "properties": {
        "doctor_id": {
          "type": "integer",
          "description": "Internal ID of the doctor",
          "title": "Doctor Id"
        },
        "date": {
          "type": "string",
          "description": "Date in YYYY-MM-DD format",
          "title": "Date"
        }
      },
      "required": [
        "doctor_id",
        "date"
      ]
    }

Tool response:
Tool: reschedule_appointment
Description: Update the datetime of an appointment to a new time slot.
Parameters:
    {
      "type": "object",
      "properties": {
        "appointment_id": {
          "type": "integer",
          "title": "Appointment Id",
          "description": ""
        },
        "new_datetime": {
          "type": "string",
          "title": "New Datetime"
        }
      },
      "required": [
        "appointment_id",
        "new_datetime"
      ]
    }

Tool response:
Tool: create_notification
Description: Send a notification to a patient about their appointment rescheduling.
Parameters:
    {
      "type": "object",
      "properties": {
        "recipient_user_id": {
          "type": "integer",
          "title": "Recipient User Id"
        },
        "appointment_id": {
          "type": "integer",
          "title": "Appointment Id"
        },
        "channel": {
          "type": "string",
          "title": "Channel"
        },
        "message": {
          "type": "string",
          "title": "Message"
        }
      },
      "required": [
        "recipient_user_id",
        "appointment_id",
        "channel",
        "message"
      ]
    }
